"""The 90 fixed instructions and verifier contracts in hybrid-tools-v1."""

from __future__ import annotations

from datetime import datetime

from bench_env.task.core.model import HybridTaskSpec, goal


def _ts(value: str) -> int:
    return int(datetime.fromisoformat(value).timestamp() * 1000)


def _spec(
    task_id: str,
    instruction: str,
    apps: list[str],
    profiles: list[str],
    goals,
    changes: list[str],
    tools: list[str],
    *,
    gui: bool,
    tags: list[str] | None = None,
    max_steps: int = 45,
) -> HybridTaskSpec:
    return HybridTaskSpec(
        task_id=task_id,
        instruction=instruction,
        apps=tuple(apps),
        setup_profiles=tuple(profiles),
        goals=tuple(goals),
        expected_changes=tuple(changes),
        candidate_tools=tuple(tools),
        gui_required=gui,
        tags=tuple(tags or []),
        max_steps=max_steps,
    )


